expr=SOPform(xs,[a for a,b in zip(s["inputs"],s["outputs"]) if b==1])
terms=expr.args if expr.func is Or else (expr,)
ops=[]
def put(t, idx, value):
    if value:
        ops.append({"op":"set","tensor":t,"index":idx,"value":float(value)})
for row,term in enumerate(terms):
    lits=term.args if term.func is And else (term,)
    positives=0
    for lit in lits:
